def check_hust_obc_undeciphered_local_review_sheets(root: Path) -> list[str]:
    issues: list[str] = []
    rows, row_issues = _read_csv_rows(root / HUST_OBC_UNDECIPHERED_CANDIDATE_INDEX)
    issues.extend(row_issues)
    if len(rows) != 9408:
        issues.append(f"{HUST_OBC_UNDECIPHERED_CANDIDATE_INDEX} should contain 9408 rows")
        return issues
    sample_rows = [rows[0], rows[6293], rows[-1]]
    required_snippets = [
        "Concrete Questions To Check",
        "具体待查问题",
        "应先核对哪一张 HUST-OBC 来源图像？",
        "哪些字形、codepoint 或后世字形路线只是候选线索？",
        "还缺哪些卜辞、图版、馆藏、出土地或时期上下文？",
        "正式释读或身份判断前还缺哪些证据？",
        "No formal reading or identity claim added",
        "Identity claim status / 身份结论状态: `no_identity_claim`",
        "Decipherment claim status / 释读结论状态: `no_claim`",
    ]
    for row in sample_rows:
        project_id = row.get("unknown_candidate_id", "")
        packet_path = root / row.get("materialized_candidate_packet_path", "")
        review_sheet_path = packet_path.parent / "05_human-review-sheet.md"
        if not path_exists(review_sheet_path):
            issues.append(f"{review_sheet_path.relative_to(root).as_posix()} missing")
            continue
        review_sheet = review_sheet_path.read_text(encoding="utf-8")
        for snippet in required_snippets:
            if snippet not in review_sheet:
                issues.append(f"{review_sheet_path.relative_to(root).as_posix()} missing marker: {snippet}")
        for line_number, line in enumerate(review_sheet.splitlines(), start=1):
            if not line.startswith("|") and len(line) > 80:
                issues.append(
                    f"{review_sheet_path.relative_to(root).as_posix()} line "
                    f"{line_number} exceeds 80 characters"
                )
        if project_id and project_id not in review_sheet:
            issues.append(f"{review_sheet_path.relative_to(root).as_posix()} missing project ID")
    return issues


def check_character_object_material_coverage_audit(root: Path) -> list[str]:
    issues: list[str] = []
    audit_path = root / CHARACTER_OBJECT_MATERIAL_COVERAGE_AUDIT
    summary_path = root / CHARACTER_OBJECT_MATERIAL_COVERAGE_SUMMARY
    with audit_path.open("r", encoding="utf-8-sig", newline="") as file:
        rows = list(csv.DictReader(file))
    summary = json.loads(summary_path.read_text(encoding="utf-8"))
    required_fields = {
        "coverage_audit_id",
        "project_id",
        "project_id_type",
        "object_dir",
        "ai_packet_path",
        "human_readme_path",
        "ai_visual_source_index_path",
        "human_visual_gallery_path",
        "local_visual_asset_count",
        "parallel_human_directory_present",
        "material_bundle_status",
        "next_material_engineering_step",
        "research_boundary",
        "decipherment_claim_status",
    }
    if len(rows) != 10996:
        issues.append(f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_AUDIT} row count changed")
    if rows:
        missing_fields = required_fields - set(rows[0])
        if missing_fields:
            issues.append(
                f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_AUDIT} missing fields: "
                f"{', '.join(sorted(missing_fields))}"
            )
    status_counts = Counter(row.get("material_bundle_status", "") for row in rows)
    expected_status_counts = {
        "object_local_bundle_with_review_image": 10996,
    }
    if dict(status_counts) != expected_status_counts:
        issues.append(f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_AUDIT} status counts changed")
    project_type_counts = Counter(row.get("project_id_type", "") for row in rows)
    if dict(project_type_counts) != {"obs-char": 1588, "obs-unk": 9408}:
        issues.append(f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_AUDIT} project ID type counts changed")
    for row in rows:
        row_id = row.get("coverage_audit_id", "")
        if not row.get("object_dir", "").startswith("corpus/001_oracle-characters/"):
            issues.append(f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_AUDIT} object outside corpus: {row_id}")
        if row.get("parallel_human_directory_present") != "false":
            issues.append(f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_AUDIT} parallel human directory present: {row_id}")
        if row.get("decipherment_claim_status") != "no_claim":
            issues.append(f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_AUDIT} decipherment claim changed: {row_id}")
        boundary = row.get("research_boundary", "")
        if "not_scholarship" not in boundary or "not a decipherment conclusion" not in boundary:
            issues.append(f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_AUDIT} boundary missing caution: {row_id}")
    expected_summary_values = {
        "object_directory_count": 10996,
        "project_id_type_counts": {"obs-char": 1588, "obs-unk": 9408},
        "human_readme_count": 10996,
        "human_visual_gallery_count": 10996,
        "ai_packet_count": 10996,
        "ai_visual_source_index_count": 10996,
        "local_visual_asset_object_count": 10996,
        "complete_object_local_bundle_count": 10996,
        "missing_human_entry_count": 0,
        "parallel_human_directory_count": 0,
    }
    for key, expected in expected_summary_values.items():
        if summary.get(key) != expected:
            issues.append(f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_SUMMARY} {key} changed")
    if "not a decipherment conclusion" not in summary.get("research_boundary", ""):
        issues.append(f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_SUMMARY} boundary missing caution")
    if "does not start formal decipherment research" not in summary.get("completion_boundary", ""):
        issues.append(f"{CHARACTER_OBJECT_MATERIAL_COVERAGE_SUMMARY} completion boundary changed")
    return issues


def check_object_local_material_coverage_audit(root: Path) -> list[str]:
    issues: list[str] = []
    audit_path = root / OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT
    summary_path = root / OBJECT_LOCAL_MATERIAL_COVERAGE_SUMMARY
    with audit_path.open("r", encoding="utf-8-sig", newline="") as file:
        rows = list(csv.DictReader(file))
    summary = json.loads(summary_path.read_text(encoding="utf-8"))
    required_fields = {
        "coverage_audit_id",
        "corpus_area",
        "project_id",
        "source_ids",
        "record_type",
        "object_dir",
        "packet_path",
        "human_file_count",
        "ai_file_count",
        "missing_human_files",
        "missing_ai_files",
        "local_visual_asset_count",
        "route_file_count",
        "parallel_human_directory_present",
        "material_bundle_status",
        "research_boundary",
        "decipherment_claim_status",
    }
    if len(rows) != 29754:
        issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} row count changed")
    if rows:
        missing_fields = required_fields - set(rows[0])
        if missing_fields:
            issues.append(
                f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} missing fields: "
                f"{', '.join(sorted(missing_fields))}"
            )
    expected_area_counts = {
        "codepoint_crosswalk_candidates": 1588,
        "collection_object_candidates": 56,
        "evolution_correspondence_candidates": 13714,
        "graphemic_component_candidates": 2747,
        "inscription_crosswalk_candidates": 612,
        "oracle_character_candidates": 10996,
        "research_source_objects": 21,
        "research_topic_candidates": 20,
    }
    area_counts = Counter(row.get("corpus_area", "") for row in rows)
    if dict(sorted(area_counts.items())) != expected_area_counts:
        issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} corpus area counts changed")
    expected_status_counts = {
        "object_local_bundle_with_evidence_routes": 16039,
        "object_local_bundle_with_review_image": 13715,
    }
    status_counts = Counter(row.get("material_bundle_status", "") for row in rows)
    if dict(sorted(status_counts.items())) != expected_status_counts:
        issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} status counts changed")
    expected_project_id_prefixes = {
        "codepoint_crosswalk_candidates": ("obs-xwalk-cand-",),
        "collection_object_candidates": ("coll-obj-cand-",),
        "evolution_correspondence_candidates": ("obs-evo-cand-",),
        "graphemic_component_candidates": ("obs-comp-cand-",),
        "inscription_crosswalk_candidates": ("obs-insc-cw-cand-",),
        "oracle_character_candidates": ("obs-char-", "obs-unk-"),
        "research_source_objects": ("src-",),
        "research_topic_candidates": ("obs-topic-cand-",),
    }
    for row in rows:
        row_id = row.get("coverage_audit_id", "")
        corpus_area = row.get("corpus_area", "")
        project_id = row.get("project_id", "")
        if not row.get("object_dir", "").startswith("corpus/"):
            issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} object outside corpus: {row_id}")
        expected_prefixes = expected_project_id_prefixes.get(corpus_area, ())
        if expected_prefixes and not project_id.startswith(expected_prefixes):
            issues.append(
                f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} project ID prefix changed: {row_id}"
            )
        if not row.get("source_ids", ""):
            issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} missing source_ids: {row_id}")
        if row.get("parallel_human_directory_present") != "false":
            issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} parallel human directory present: {row_id}")
        if row.get("decipherment_claim_status") != "no_claim":
            issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} decipherment claim changed: {row_id}")
        if row.get("missing_human_files") or row.get("missing_ai_files"):
            issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} missing object-local bundle file: {row_id}")
        boundary = row.get("research_boundary", "")
        if "not_scholarship" not in boundary or "decipherment conclusions" not in boundary:
            issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT} boundary missing caution: {row_id}")
    expected_summary_values = {
        "object_directory_count": 29754,
        "corpus_area_counts": expected_area_counts,
        "material_bundle_status_counts": expected_status_counts,
        "human_entry_object_count": 29754,
        "ai_entry_object_count": 29754,
        "local_visual_asset_object_count": 13715,
        "route_gallery_or_route_index_object_count": 29754,
        "partial_or_missing_bundle_count": 0,
        "parallel_human_directory_count": 0,
    }
    for key, expected in expected_summary_values.items():
        if summary.get(key) != expected:
            issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_SUMMARY} {key} changed")
    if "formal decipherment research" not in summary.get("completion_boundary", ""):
        issues.append(f"{OBJECT_LOCAL_MATERIAL_COVERAGE_SUMMARY} completion boundary changed")
    return issues


def check_object_local_human_research_depth_audit(root: Path) -> list[str]:
    issues: list[str] = []
    audit_path = root / OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT
    summary_path = root / OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_SUMMARY
    guide_path = root / OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_GUIDE
    with audit_path.open("r", encoding="utf-8-sig", newline="") as file:
        rows = list(csv.DictReader(file))
    summary = json.loads(summary_path.read_text(encoding="utf-8"))
    guide = guide_path.read_text(encoding="utf-8")
    required_guide_markers = (
        "Human-First Research Depth Guide",
        "Current Baseline / 当前基线",
        "Area Review Map / 分区复核地图",
        "Completion Boundary / 完成边界",
        "object-local dossiers",
        "结构化文件只服务检索、追溯、比较和审计",
    )
    for marker in required_guide_markers:
        if marker not in guide:
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_GUIDE} missing marker: {marker}")
    for line_number, line in enumerate(guide.splitlines(), start=1):
        if len(line) > 80:
            issues.append(
                f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_GUIDE}:{line_number} exceeds 80 chars"
            )
    required_fields = {
        "depth_audit_id",
        "corpus_area",
        "object_count",
        "human_entry_object_count",
        "ai_entry_object_count",
        "complete_bundle_object_count",
        "representative_human_files_to_open",
        "required_human_slots",
        "concrete_depth_questions",
        "coverage_source_file",
        "human_first_boundary",
        "depth_review_status",
        "claim_boundary",
    }
    if len(rows) != 8:
        issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} row count changed")
    if rows:
        missing_fields = required_fields - set(rows[0])
        if missing_fields:
            issues.append(
                f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} missing fields: "
                f"{', '.join(sorted(missing_fields))}"
            )
    expected_area_counts = {
        "codepoint_crosswalk_candidates": 1588,
        "collection_object_candidates": 56,
        "evolution_correspondence_candidates": 13714,
        "graphemic_component_candidates": 2747,
        "inscription_crosswalk_candidates": 612,
        "oracle_character_candidates": 10996,
        "research_source_objects": 21,
        "research_topic_candidates": 20,
    }
    by_area = {row.get("corpus_area", ""): row for row in rows}
    if set(by_area) != set(expected_area_counts):
        issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} corpus areas changed")
    required_slot_markers = {
        "oracle_character_candidates": [
            "glyph_observation",
            "inscription_context",
            "decipherment_history",
            "later_script_routes",
            "opened_glyph_image_observation",
            "formal_character_research_blockers",
            "source_manifest_checksum_field_map",
        ],
        "inscription_crosswalk_candidates": [
            "inscription_number",
            "ocr_or_full_text",
            "plate_number",
            "text_quality",
            "preformal_research_opening_order",
        ],
        "graphemic_component_candidates": [
            "component_boundary",
            "near_shape",
            "host_character",
        ],
        "evolution_correspondence_candidates": [
            "bronze_seal_modern_route",
            "cross_period_comparison",
        ],
        "codepoint_crosswalk_candidates": [
            "source_codepoint",
            "matched_project_character_route",
        ],
        "collection_object_candidates": [
            "institution",
            "findspot",
            "rights_status",
        ],
        "research_source_objects": [
            "checksum",
            "package_manifest",
            "field_map",
            "derived_paths",
        ],
        "research_topic_candidates": [
            "bibliographic_identity",
            "citation_relation",
            "different_opinions",
            "dispute_record",
        ],
    }
    for area, expected_count in expected_area_counts.items():
        row = by_area.get(area)
        if row is None:
            continue
        row_id = row.get("depth_audit_id", "")
        if row.get("object_count") != str(expected_count):
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} object count changed: {area}")
        if row.get("human_entry_object_count") != str(expected_count):
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} human entry count changed: {area}")
        if row.get("ai_entry_object_count") != str(expected_count):
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} ai entry count changed: {area}")
        if row.get("complete_bundle_object_count") != str(expected_count):
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} bundle count changed: {area}")
        if not row.get("representative_human_files_to_open", "").startswith("corpus/"):
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} missing representative human file: {row_id}")
        if row.get("coverage_source_file") != OBJECT_LOCAL_MATERIAL_COVERAGE_AUDIT:
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} coverage source changed: {row_id}")
        if row.get("depth_review_status") != "needs_human_research_depth_review":
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} review status changed: {row_id}")
        if not row.get("human_first_boundary", "").startswith("human dossier first"):
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} human-first boundary changed: {row_id}")
        claim_boundary = row.get("claim_boundary", "")
        if "not_scholarship" not in claim_boundary or "no_decipherment_claim" not in claim_boundary:
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} claim boundary changed: {row_id}")
        slots = row.get("required_human_slots", "")
        for marker in required_slot_markers[area]:
            if marker not in slots:
                issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} missing slot {marker}: {row_id}")
        if "Which " not in row.get("concrete_depth_questions", ""):
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_AUDIT} missing concrete question: {row_id}")
    expected_summary_values = {
        "area_count": 8,
        "object_directory_count": 29754,
        "human_entry_object_count": 29754,
        "ai_entry_object_count": 29754,
        "complete_bundle_object_count": 29754,
        "partial_or_missing_bundle_count": 0,
        "parallel_human_directory_count": 0,
        "depth_review_status_counts": {"needs_human_research_depth_review": 8},
    }
    for key, expected in expected_summary_values.items():
        if summary.get(key) != expected:
            issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_SUMMARY} {key} changed")
    if "routes humans to object-local dossiers" not in summary.get("completion_boundary", ""):
        issues.append(f"{OBJECT_LOCAL_HUMAN_RESEARCH_DEPTH_SUMMARY} completion boundary changed")
    return issues


