    image_profile_rows, image_profile_issues = _read_csv_rows(root / ASSET_IMAGE_TECHNICAL_PROFILE)
    visual_profile_rows, visual_profile_issues = _read_csv_rows(root / ASSET_IMAGE_VISUAL_PROFILE)
